DROP TABLE IF EXISTS `live_device_sessions`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8mb4 */;
CREATE TABLE `live_device_sessions` (
  `user_id` int(10) unsigned NOT NULL,
  `device_uuid` varchar(64) NOT NULL,
  `ip_address` varchar(64) DEFAULT NULL,
  `user_agent` varchar(255) DEFAULT NULL,
  `started_at` datetime NOT NULL DEFAULT utc_timestamp(),
  `last_seen_at` datetime NOT NULL DEFAULT utc_timestamp(),
  `session_expires_at` datetime NOT NULL,
  PRIMARY KEY (`user_id`,`device_uuid`),
  KEY `idx_live_sessions_expires` (`session_expires_at`),
  KEY `idx_live_sessions_device` (`device_uuid`),
  CONSTRAINT `fk_live_sessions_user` FOREIGN KEY (`user_id`) REFERENCES `reg_users` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_uca1400_ai_ci;
