CREATE DEFINER=`starstream`@`localhost` PROCEDURE `spm_live_cat`(
    IN p_id INT UNSIGNED
)
BEGIN
    IF p_id IS NULL THEN
        SELECT
            id,
            category,
            created_at,
            updated_at
        FROM live_categories
        ORDER BY category ASC;
    ELSE
        SELECT
            id,
            category,
            created_at,
            updated_at
        FROM live_categories
        WHERE id = p_id
        LIMIT 1;
    END IF;
END ;;
