CREATE DEFINER=`starstream`@`localhost` PROCEDURE `spm_live_channels_create`(
    IN  p_channel_key  VARCHAR(8),
    IN  p_name         VARCHAR(255),
    IN  p_number       INT,
    IN  p_category_id  INT,
    IN  p_logo_file_id INT,
    IN  p_source_uri   TEXT,
    IN  p_bitrate_kbps INT,
    IN  p_enabled      TINYINT,
    IN  p_description  TEXT,
    OUT o_id           INT
)
BEGIN
    IF p_channel_key IS NULL OR p_channel_key = ''
       OR p_name IS NULL OR p_name = ''
       OR p_source_uri IS NULL OR p_source_uri = ''
       OR p_number IS NULL OR p_number < 1 THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'INVALID_INPUT';
    END IF;

    IF p_channel_key NOT REGEXP '^[A-Z0-9]{8}$' THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'INVALID_CHANNEL_KEY';
    END IF;

    INSERT INTO live_channels
        (channel_key, name, number, category_id, logo_file_id,
         source_uri, bitrate_kbps, enabled, description)
    VALUES
        (UPPER(TRIM(p_channel_key)),
         TRIM(p_name),
         p_number,
         p_category_id,
         p_logo_file_id,
         TRIM(p_source_uri),
         p_bitrate_kbps,
         IFNULL(p_enabled, 1),
         NULLIF(TRIM(p_description), ''));

    SET o_id = LAST_INSERT_ID();
END ;;
DELIMITER ;
