CREATE DEFINER=`starstream`@`localhost` PROCEDURE `spm_live_channels_delete`(
    IN p_id INT
)
BEGIN
    IF p_id IS NULL OR p_id < 1 THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'INVALID_ID';
    END IF;

    DELETE FROM live_channels WHERE id = p_id;

    IF ROW_COUNT() = 0 THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'NOT_FOUND';
    END IF;
END ;;
