CREATE DEFINER=`starstream`@`localhost` PROCEDURE `spm_live_channels_get`(
    IN p_id INT
)
BEGIN
    IF p_id IS NULL OR p_id < 1 THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'INVALID_ID';
    END IF;

    SELECT
        id,
        channel_key,
        name,
        number,
        category_id,
        logo_file_id,
        source_uri,
        bitrate_kbps,
        enabled,
        description,
        created_at,
        updated_at
    FROM live_channels
    WHERE id = p_id
    LIMIT 1;
END ;;
