CREATE DEFINER=`starstream`@`localhost` PROCEDURE `spm_live_channels_list`(
    IN p_limit        INT,
    IN p_offset       INT,
    IN p_enabled      TINYINT,
    IN p_category_id  INT,
    IN p_q            VARCHAR(255)
)
BEGIN
    SELECT
        lc.id,
        lc.channel_key,
        lc.name,
        lc.number,
        lc.category_id,
        lc.logo_file_id,
        lc.source_uri,
        lc.bitrate_kbps,
        lc.enabled,
        lc.description,
        lc.created_at,
        lc.updated_at
    FROM live_channels lc
    WHERE
        (p_enabled IS NULL OR lc.enabled = p_enabled)
        AND (p_category_id IS NULL OR lc.category_id = p_category_id)
        AND (p_q IS NULL OR p_q = '' OR lc.name LIKE CONCAT('%', p_q, '%'))
    ORDER BY lc.number ASC;

    SELECT COUNT(*) AS total
    FROM live_channels lc
    WHERE
        (p_enabled IS NULL OR lc.enabled = p_enabled)
        AND (p_category_id IS NULL OR lc.category_id = p_category_id)
        AND (p_q IS NULL OR p_q = '' OR lc.name LIKE CONCAT('%', p_q, '%'));
END ;;
