CREATE DEFINER=`starstream`@`localhost` PROCEDURE `spm_live_channels_update`(
    IN p_id            INT,
    IN p_channel_key   VARCHAR(8),
    IN p_name          VARCHAR(255),
    IN p_number        INT,
    IN p_category_id   INT,
    IN p_logo_file_id  INT,
    IN p_source_uri    TEXT,
    IN p_bitrate_kbps  INT,
    IN p_enabled       TINYINT,
    IN p_description   TEXT
)
BEGIN
    IF p_id IS NULL OR p_id < 1 THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'INVALID_ID';
    END IF;

    IF p_channel_key IS NOT NULL
       AND p_channel_key NOT REGEXP '^[A-Z0-9]{8}$' THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'INVALID_CHANNEL_KEY';
    END IF;

    IF p_number IS NOT NULL AND p_number < 1 THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'INVALID_NUMBER';
    END IF;

    UPDATE live_channels
    SET
        channel_key   = COALESCE(UPPER(TRIM(p_channel_key)), channel_key),
        name          = COALESCE(TRIM(p_name), name),
        number        = COALESCE(p_number, number),
        category_id   = IF(p_category_id IS NULL, category_id, p_category_id),
        logo_file_id  = IF(p_logo_file_id IS NULL, logo_file_id, p_logo_file_id),
        source_uri    = COALESCE(TRIM(p_source_uri), source_uri),
        bitrate_kbps  = IF(p_bitrate_kbps IS NULL, bitrate_kbps, p_bitrate_kbps),
        enabled       = IF(p_enabled IS NULL, enabled, IF(p_enabled = 1, 1, 0)),
        description   = IF(p_description IS NULL, description, NULLIF(TRIM(p_description), '')),
        updated_at    = CURRENT_TIMESTAMP()
    WHERE id = p_id;

    IF ROW_COUNT() = 0 THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'NOT_FOUND';
    END IF;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
