CREATE DEFINER=`starstream`@`localhost` PROCEDURE `spm_session`(
    IN p_session_id CHAR(64)
        CHARACTER SET utf8mb4
        COLLATE utf8mb4_uca1400_ai_ci
)
BEGIN
    SELECT
        s.session_id,
        s.admin_id,
        s.created_at,
        s.last_seen_at,
        s.expires_at,
        s.is_revoked,

        u.status AS admin_status,
        u.username,
        u.full_name,
        u.email

    FROM admin_sessions s
    JOIN admin_users u ON u.id = s.admin_id
    WHERE s.session_id = p_session_id
    LIMIT 1;
END ;;
