CREATE DEFINER=`starstream`@`localhost` PROCEDURE `spm_session_create`(
    IN p_session_id CHAR(64)
        CHARACTER SET utf8mb4
        COLLATE utf8mb4_uca1400_ai_ci,

    IN p_admin_id INT UNSIGNED,
    IN p_expires_at DATETIME,

    IN p_ip VARCHAR(64)
        CHARACTER SET utf8mb4
        COLLATE utf8mb4_uca1400_ai_ci,

    IN p_ua VARCHAR(255)
        CHARACTER SET utf8mb4
        COLLATE utf8mb4_uca1400_ai_ci
)
BEGIN
    DECLARE v_now DATETIME DEFAULT UTC_TIMESTAMP();

    INSERT INTO admin_sessions (
        session_id,
        admin_id,
        ip_address,
        user_agent,
        created_at,
        last_seen_at,
        expires_at,
        is_revoked
    ) VALUES (
        p_session_id,
        p_admin_id,
        NULLIF(p_ip, ''),
        NULLIF(p_ua, ''),
        v_now,
        v_now,
        p_expires_at,
        0
    );
END ;;
