    IN p_admin_id INT UNSIGNED,
    IN p_username VARCHAR(64),
    IN p_full_name VARCHAR(255),
    IN p_email VARCHAR(255),
    IN p_status ENUM('active','disabled','suspended'),
    IN p_must_change_password TINYINT(1)
)
BEGIN
    UPDATE admin_users
       SET username = COALESCE(p_username, username),
           full_name = p_full_name,
           email = p_email,
           status = p_status,
           must_change_password = IFNULL(p_must_change_password, must_change_password),
           updated_at = CURRENT_TIMESTAMP()
     WHERE id = p_admin_id;
END ;;
