CREATE DEFINER=`starstream`@`localhost` PROCEDURE `sps_get_account`(
    IN p_user_id INT UNSIGNED
)
BEGIN
    

    DECLARE v_now DATETIME DEFAULT UTC_TIMESTAMP();

    SELECT
        1 AS ok,

        ru.id AS accountId,

        
        ru.username AS accountNumber,

        
        COALESCE(NULLIF(ru.full_name, ''), ru.username) AS accountName,

        ru.email AS email,

        
        (UNIX_TIMESTAMP(ru.created_at) * 1000) AS dateRegistered,

        
        CASE
            WHEN ru.status = 'disabled' THEN 'DISCONNECTED'
            WHEN ru.status = 'suspended' THEN 'SUSPENDED'
            WHEN ru.account_expiry IS NOT NULL AND ru.account_expiry <= v_now THEN 'EXPIRED'
            ELSE 'ACTIVE'
        END AS status,

        
        COALESCE(
            (
                SELECT p.name
                  FROM user_packages up
                  JOIN packages p ON p.id = up.package_id
                 WHERE up.user_id = ru.id
                   AND up.status = 'active'
                   AND p.status = 'active'
                 ORDER BY p.id ASC
                 LIMIT 1
            ),
            'BASIC'
        ) AS packageName,

        
        0.0 AS balance

    FROM reg_users ru
    WHERE ru.id = p_user_id
    LIMIT 1;

END ;;
DELIMITER ;
