CREATE DEFINER=`starstream`@`localhost` PROCEDURE `sps_get_published_vod`()
BEGIN
  SELECT
    id,
    type,
    title,
    original_title,
    overview,
    language,
    release_date,
    year,
    runtime_seconds,
    age_rating,
    poster_url,
    status,
    created_at,
    updated_at
  FROM vod
  WHERE status = 'PUBLISHED'
  ORDER BY
