CREATE DEFINER=`starstream`@`localhost` PROCEDURE `sps_get_published_vod_by_tag`(
    IN p_tag_id BIGINT UNSIGNED
)
BEGIN
    SELECT
        v.id,
        v.type,
        v.title,
        v.original_title,
        v.overview,
        v.language,
        v.release_date,
        v.year,
        v.runtime_seconds,
        v.age_rating,
        v.poster_url,
        v.status,
        v.created_at,
        v.updated_at
    FROM vod v
    JOIN vod_tag_map m ON m.vod_id = v.id
    WHERE v.status = 'PUBLISHED'
      AND m.tag_id = p_tag_id
    ORDER BY
        COALESCE(v.release_date, v.created_at) DESC,
        v.id DESC;
END ;;
DELIMITER ;
