CREATE DEFINER=`starstream`@`localhost` PROCEDURE `sps_get_vod_detail`(
    IN p_vod_id BIGINT UNSIGNED
)
BEGIN
    
    SELECT
        id,
        type,
        title,
        original_title,
        overview,
        language,
        release_date,
        year,
        runtime_seconds,
        age_rating,
        poster_url,
        status,
        created_at,
        updated_at
    FROM vod
    WHERE id = p_vod_id
      AND status = 'PUBLISHED'
    LIMIT 1;

    
    SELECT
        t.id,
        t.name
    FROM vod_tag_map m
    JOIN vod_tags t ON t.id = m.tag_id
    WHERE m.vod_id = p_vod_id
    ORDER BY t.name ASC;
END ;;
DELIMITER ;
