/*!50003 DROP PROCEDURE IF EXISTS `sps_live_channels_by_userid` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_uca1400_ai_ci */ ;
DELIMITER ;;
CREATE DEFINER=`starstream`@`localhost` PROCEDURE `sps_live_channels_by_userid`(IN p_user_id INT UNSIGNED)
BEGIN
  DECLARE v_now DATETIME;
  SET v_now = UTC_TIMESTAMP();

  SELECT
    lc.id,
    lc.channel_key,
    lc.name,
    lc.number,
    lc.bitrate_kbps,

    
    COALESCE(lc.description, '') AS description,

    
    CASE
      WHEN cat.category IS NULL THEN JSON_ARRAY()
      ELSE JSON_ARRAY(cat.category)
    END AS categories,

    mf.uri AS logo_uri
  FROM reg_users u
  JOIN (
    SELECT DISTINCT src.channel_id
    FROM (
      SELECT pc.channel_id
      FROM user_packages up
      JOIN packages p          ON p.id = up.package_id AND p.status='active'
      JOIN package_channels pc ON pc.package_id = p.id
      WHERE up.user_id = p_user_id
        AND up.status='active'
        AND (up.starts_at IS NULL OR up.starts_at <= v_now)
        AND (up.ends_at   IS NULL OR up.ends_at   >  v_now)

      UNION

      SELECT o.channel_id
      FROM user_channel_overrides o
      WHERE o.user_id = p_user_id
        AND o.mode = 'allow'
    ) src
    LEFT JOIN user_channel_overrides deny
      ON deny.user_id = p_user_id
     AND deny.channel_id = src.channel_id
     AND deny.mode = 'deny'
    WHERE deny.user_id IS NULL
  ) allowed ON 1=1
  JOIN live_channels lc ON lc.id = allowed.channel_id
  LEFT JOIN live_categories cat ON cat.id = lc.category_id
  LEFT JOIN media_files mf      ON mf.id  = lc.logo_file_id
  WHERE u.id = p_user_id
    AND u.status='active'
    AND (u.account_expiry IS NULL OR u.account_expiry > v_now)
    AND lc.enabled = 1
  ORDER BY lc.number ASC;
END ;;
DELIMITER ;
